"use client";

import { useCallback, useState } from "react";
import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";
import { Button } from "@/modules/ui/components/button";
import { H4, Small } from "@/modules/ui/components/typography";

interface AccountActivityProps {
  user: TUser;
}

export const AccountActivity = ({ user }: Readonly<AccountActivityProps>) => {
  const { t } = useTranslation();
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownload = useCallback(async () => {
    setIsDownloading(true);
    try {
      const response = await fetch("/api/user/download");
      if (!response.ok) {
        throw new Error("Download failed");
      }
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `formbricks-data-${new Date().toISOString().split("T")[0]}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error("Failed to download user data:", error);
    } finally {
      setIsDownloading(false);
    }
  }, []);

  return (
    <div>
      <div className="mb-4 flex items-center gap-8">
        <div>
          <H4 className="mb-1 font-medium tracking-normal">
            {t("workspace.settings.profile.account_created")}
          </H4>
          <Small color="muted">
            {user.createdAt.toLocaleDateString(undefined, {
              year: "numeric",
              month: "long",
              day: "numeric",
            })}
          </Small>
        </div>
        <div>
          <H4 className="mb-1 font-medium tracking-normal">
            {t("workspace.settings.profile.last_login")}
          </H4>
          <Small color="muted">
            {user.lastLoginAt
              ? user.lastLoginAt.toLocaleDateString(undefined, {
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })
              : t("common.never")}
          </Small>
        </div>
      </div>
      <Button
        variant="outline"
        size="sm"
        loading={isDownloading}
        onClick={handleDownload}>
        {t("workspace.settings.profile.download_my_data")}
      </Button>
    </div>
  );
};

import { NextResponse } from "next/server";
import { getSession } from "@/modules/auth/lib/session";
import { getUser } from "@/lib/user/service";
import { lookupAuthorizedOrganizationIds } from "@/lib/authorization/resource-list";

export const GET = async () => {
  const session = await getSession();

  if (!session?.user) {
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  }

  const user = await getUser(session.user.id);

  if (!user) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  // Fetch user's organizations with their membership role
  const organizationIds = await lookupAuthorizedOrganizationIds({
    type: "user",
    id: session.user.id,
  });

  const { prisma } = await import("@formbricks/database");
  const memberships = await prisma.membership.findMany({
    where: {
      userId: session.user.id,
      organizationId: { in: organizationIds },
    },
    select: {
      organization: {
        select: {
          id: true,
          name: true,
        },
      },
      role: true,
    },
  });

  const downloadData = {
    name: user.name,
    email: user.email,
    locale: user.locale,
    notificationSettings: user.notificationSettings,
    organizations: memberships.map((m) => ({
      organizationId: m.organization.id,
      organizationName: m.organization.name,
      role: m.role,
    })),
  };

  const json = JSON.stringify(downloadData, null, 2);
  const filename = `formbricks-data-${new Date().toISOString().split("T")[0]}.json`;

  return new NextResponse(json, {
    status: 200,
    headers: {
      "Content-Type": "application/json",
      "Content-Disposition": `attachment; filename="${filename}"`,
    },
  });
};

